/// 粗糙度正規化尺度（公尺），與危險門檻一致
const ROUGH_SCALE_M: f32 = 0.3;
/// 科學價值場的影響半徑（公尺）
const SCIENCE_RADIUS_M: f32 = 80.0;
/// 起訖點落在危險區時，往外找可通行格的最大距離（公尺）
const SNAP_RADIUS_M: f32 = 30.0;

#[derive(Clone, Copy, Debug, Deserialize, Serialize, PartialEq)]
pub struct Obstacle {
    pub x: f32,
    pub y: f32,
    pub r: f32,
}

#[derive(Debug, Clone, PartialEq)]
pub enum PlanError {
    OutOfBounds,
    Blocked,
    NoPath,
}

#[derive(Debug, Clone, Serialize)]
pub struct Route {
    pub mode: Mode,
    pub path: Vec<[f32; 3]>,
    pub length_m: f32,
    pub eta_min: f32,
    pub dose_msv: f32,
    pub max_slope_deg: f32,
    pub min_clearance_m: f32,
    pub risk: f32,
    pub cost: f32,
    pub notes: Vec<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct Replan {
    pub route: Option<Route>,
    pub must_return: bool,
    pub return_route: Option<Route>,
    pub reason: &'static str,
    /// 走到目標再回基地的總時間（分鐘），無法到達時為 null
    pub round_trip_min: Option<f32>,
}

pub struct Planner {
    pub dem: Grid<f32>,
    pub slope: Grid<f32>,
    pub rough: Grid<f32>,
    pub hazard: Grid<bool>,
    pub clearance: Grid<f32>,
    pub science: Grid<f32>,
    /// 每公尺秒數
    pub spm: Grid<f32>,
    pub costs: [Grid<f32>; 3],
    /// 每格回到基地的步行時間（分鐘）
    pub t_base_min: Grid<f32>,
    pub base: (f32, f32),
    pub base_idx: usize,
    pub targets: Vec<Target>,
    pub params: MissionParams,
    pub thresholds: HazardThresholds,
    pub beacons: Vec<Beacon>,
    /// 每格可見信標數
    pub coverage: Grid<f32>,
}

/// 導航狀態（給 HUD 用）：偏離路線距離、下一個導引點、狀態、回基地時間。
#[derive(Debug, Clone, Serialize)]
pub struct NavStatus {
    pub xte_m: f32,
    pub along_m: f32,
    pub remaining_m: f32,
    /// 沿路線前方 `lookahead` 公尺的導引點
    pub next: [f32; 2],
    /// 路線在太空人的哪一側：+1 左、−1 右（以路線前進方向看）
    pub side: f32,
    pub status: RouteStatus,
    pub reason: &'static str,
    /// 到最近危險區的距離（公尺）
    pub clearance_m: f32,
    /// 從此處走回基地的時間（分鐘；不含新回報的障礙）
    pub t_return_min: f32,
    /// 此處可見的信標數
    pub coverage: f32,
}

/// 「覆蓋不足」懲罰：0 個可見信標 → 1，≥ 3 個 → 0。
fn comm_penalty(cov: &Grid<f32>) -> Grid<f32> {
    cov.map(|c| (1.0 - c.min(3.0) / 3.0).max(0.0))
}

fn mode_idx(m: Mode) -> usize {
    match m {
        Mode::Safe => 0,
        Mode::Balanced => 1,
        Mode::Science => 2,
    }
}

impl Planner {
    pub fn new(world: &World, params: MissionParams) -> Self {
        let slope = slope_deg(&world.dem);
        let rough = roughness(&world.dem);
        let thresholds = HazardThresholds {
            slope_max_deg: params.slope_max_deg,
            ..HazardThresholds::default()
        };
        let hazard = hazard_mask(&slope, &rough, thresholds);
        let science = science_field(world, SCIENCE_RADIUS_M);
        let cov = coverage(&world.dem, &world.beacons, &params.nav, 4);
        let base_idx = {
            let (i, j) = world
                .dem
                .to_cell(world.base.0, world.base.1)
                .expect("base outside map");
            world.dem.idx(i, j)
        };
        Self::assemble(
            world.dem.clone(),
            slope,
            rough,
            hazard,
            science,
            world.base,
            base_idx,
            world.targets.clone(),
            params,
            thresholds,
            world.beacons.clone(),
            cov,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn assemble(
        dem: Grid<f32>,
        slope: Grid<f32>,
        rough: Grid<f32>,
        mut hazard: Grid<bool>,
        science: Grid<f32>,
        base: (f32, f32),
        base_idx: usize,
        targets: Vec<Target>,
        params: MissionParams,
        thresholds: HazardThresholds,
        beacons: Vec<Beacon>,
        coverage: Grid<f32>,
    ) -> Self {
        hazard.data[base_idx] = false; // 基地本身一定可站
        let clearance = distance_to(&hazard);
        let comm = comm_penalty(&coverage);
        let inp = CostInputs {
            slope: &slope,
            rough: &rough,
            hazard: &hazard,
            clearance: &clearance,
            science: &science,
            comm: &comm,
            slope_max_deg: thresholds.slope_max_deg,
            rough_scale_m: ROUGH_SCALE_M,
        };
        let costs = Mode::ALL.map(|m| cost_map(&inp, &CostWeights::for_mode(m)));
        let spm = seconds_per_m(
            &slope,
            &rough,
            &hazard,
            params.walk_speed_mps,
            ROUGH_SCALE_M,
        );
        let t_base_min = dijkstra_field(&spm, base_idx).map(|s| s / 60.0);
        Self {
            dem,
            slope,
            rough,
            hazard,
            clearance,
            science,
            spm,
            costs,
            t_base_min,
            base,
            base_idx,
            targets,
            params,
            thresholds,
            beacons,
            coverage,
        }
    }

    /// 加入回報的障礙（圓盤）後重建規劃器。
    pub fn with_obstacles(&self, obstacles: &[Obstacle]) -> Self {
        let mut hazard = self.hazard.clone();
        for o in obstacles {
            stamp_disk(&mut hazard, o);
        }
        Self::assemble(
            self.dem.clone(),
            self.slope.clone(),
            self.rough.clone(),
            hazard,
            self.science.clone(),
            self.base,
            self.base_idx,
            self.targets.clone(),
            self.params.clone(),
            self.thresholds,
            self.beacons.clone(),
            self.coverage.clone(),
        )
    }

    /// HUD 用的導航狀態：估計位置 + 不確定度 + 目前路線。
    pub fn track(
        &self,
        pos: (f32, f32),
        sigma_m: f32,
        path: &[[f32; 3]],
        lookahead_m: f32,
    ) -> Result<NavStatus, PlanError> {
        if path.len() < 2 {
            return Err(PlanError::NoPath);
        }
        let (i, j) = self
            .dem
            .to_cell(pos.0, pos.1)
            .ok_or(PlanError::OutOfBounds)?;
        let k = self.dem.idx(i, j);
        let t = cross_track(path, pos);
        let clearance = if self.hazard.data[k] {
            0.0
        } else {
            self.clearance.data[k]
        };
        let (status, reason) = assess(t.xte_m, sigma_m, clearance, &self.params.nav);
        Ok(NavStatus {
            xte_m: t.xte_m,
            along_m: t.along_m,
            remaining_m: (t.total_m - t.along_m).max(0.0),
            next: point_along(path, t.along_m + lookahead_m),
            side: t.side,
            status,
            reason,
            clearance_m: clearance.min(1e5),
            t_return_min: self.t_base_min.data[k],
            coverage: self.coverage.data[k],
        })
    }

    pub fn cost(&self, m: Mode) -> &Grid<f32> {
        &self.costs[mode_idx(m)]
    }

    /// 公尺座標 → 可通行格；落在危險區時往外找 SNAP_RADIUS_M 內最近的可通行格。
    pub fn locate(&self, p: (f32, f32)) -> Result<usize, PlanError> {
        let (i, j) = self.dem.to_cell(p.0, p.1).ok_or(PlanError::OutOfBounds)?;
        let k = self.dem.idx(i, j);
        if !self.hazard.data[k] {
            return Ok(k);
        }
        let r = (SNAP_RADIUS_M / self.dem.cell_m).ceil() as isize;
        let mut best: Option<(isize, usize)> = None;
        for dj in -r..=r {
            for di in -r..=r {
                let (ni, nj) = (i as isize + di, j as isize + dj);
                if !self.dem.in_bounds(ni, nj) {
                    continue;
                }
                let n = self.dem.idx(ni as usize, nj as usize);
                let d2 = di * di + dj * dj;
                if d2 <= r * r && !self.hazard.data[n] && best.is_none_or(|(bd, _)| d2 < bd) {
                    best = Some((d2, n));
                }
            }
        }
        best.map(|(_, n)| n).ok_or(PlanError::Blocked)
    }

    pub fn route(
        &self,
        start: (f32, f32),
        goal: (f32, f32),
        mode: Mode,
    ) -> Result<Route, PlanError> {
        let s = self.locate(start)?;
        let g = self.locate(goal)?;
        let min_cost = CostWeights::for_mode(mode).min_cost;
        let p = astar(self.cost(mode), s, g, min_cost).ok_or(PlanError::NoPath)?;
        Ok(self.describe(&p.cells, p.cost, mode))
    }

    /// 三種模式各規劃一次（平行）。
    pub fn compare(&self, start: (f32, f32), goal: (f32, f32)) -> [Result<Route, PlanError>; 3] {
        let (a, (b, c)) = crate::par::join(
            || self.route(start, goal, Mode::Safe),
            || {
                crate::par::join(
                    || self.route(start, goal, Mode::Balanced),
                    || self.route(start, goal, Mode::Science),
                )
            },
        );
        [a, b, c]
    }

    /// 不歸點安全區：從 pos 走到該格、再從該格走回基地，總時間 ≤ 剩餘 O2 − 保留量。
    pub fn pnr_mask(&self, pos: (f32, f32), o2_min: f32) -> Result<Grid<bool>, PlanError> {
        let budget = o2_min - self.params.o2_reserve_min;
        let p = self.locate(pos)?;
        let t_pos = if p == self.base_idx {
            self.t_base_min.clone()
        } else {
            dijkstra_field(&self.spm, p).map(|s| s / 60.0)
        };
        let data = t_pos
            .data
            .iter()
            .zip(&self.t_base_min.data)
            .map(|(a, b)| a + b <= budget)
            .collect();
        Ok(Grid::from_vec(
            self.dem.w,
            self.dem.h,
            self.dem.cell_m,
            data,
        ))
    }

    /// EVA 中的重規劃。`self` 應已套用最新障礙（見 `with_obstacles`）。
    pub fn replan(
        &self,
        pos: (f32, f32),
        goal: (f32, f32),
        mode: Mode,
        had_obstacles: bool,
        o2_min: f32,
    ) -> Result<Replan, PlanError> {
        let budget = o2_min - self.params.o2_reserve_min;
        let to_base = || self.route(pos, self.base, Mode::Safe).ok();
        match self.route(pos, goal, mode) {
            Err(PlanError::NoPath) | Err(PlanError::Blocked) => Ok(Replan {
                route: None,
                must_return: true,
                return_route: to_base(),
                reason: "no_path",
                round_trip_min: None,
            }),
            Err(e) => Err(e),
            Ok(r) => {
                let g = self.locate(goal)?;
                let round = r.eta_min + self.t_base_min.data[g];
                if round > budget {
                    Ok(Replan {
                        route: None,
                        must_return: true,
                        return_route: to_base(),
                        reason: "goal_beyond_pnr",
                        round_trip_min: Some(round),
                    })
                } else {
                    let reason = if had_obstacles {
                        "obstacle_rerouted"
                    } else {
                        "ok"
                    };
                    Ok(Replan {
                        route: Some(r),
                        must_return: false,
                        return_route: None,
                        reason,
                        round_trip_min: Some(round),
                    })
                }
            }
        }
    }

    /// 由格子路徑計算統計、風險和說明文字。
    fn describe(&self, cells: &[usize], cost: f32, mode: Mode) -> Route {
        let d = &self.dem;
        let xy = |k: usize| d.center(k % d.w, k / d.w);
        let (mut length, mut secs) = (0.0f32, 0.0f32);
        for w in cells.windows(2) {
            let (a, b) = (xy(w[0]), xy(w[1]));
            let seg = ((a.0 - b.0).powi(2) + (a.1 - b.1).powi(2)).sqrt();
            length += seg;
            secs += seg * 0.5 * (self.spm.data[w[0]] + self.spm.data[w[1]]);
        }
        let eta_min = secs / 60.0;
        let (mut max_slope, mut max_slope_at) = (0.0f32, cells[0]);
        let mut min_clear = f32::INFINITY;
        let mut rough_sum = 0.0;
        for &k in cells {
            if self.slope.data[k] > max_slope {
                max_slope = self.slope.data[k];
                max_slope_at = k;
            }
            min_clear = min_clear.min(self.clearance.data[k]);
            rough_sum += self.rough.data[k];
        }
        let rough_mean = rough_sum / cells.len() as f32;
        let risk = (0.45 * (max_slope / self.thresholds.slope_max_deg).min(1.0)
            + 0.4 * (-min_clear / 20.0).exp()
            + 0.15 * (rough_mean / ROUGH_SCALE_M).min(1.0))
        .clamp(0.0, 1.0);

        let (s, g) = (xy(cells[0]), xy(*cells.last().unwrap()));
        let straight = ((s.0 - g.0).powi(2) + (s.1 - g.1).powi(2)).sqrt().max(1e-3);
        let mut notes = vec![];
        let (mx, my) = xy(max_slope_at);
        notes.push(format!(
            "Steepest section {max_slope:.0}° near ({mx:.0}, {my:.0}) m"
        ));
        if min_clear < 1e5 {
            notes.push(format!("Closest approach to a hazard: {min_clear:.0} m"));
        }
        if length / straight > 1.15 {
            notes.push(format!(
                "Detour {:.0}% longer than the straight line to avoid hazards",
                (length / straight - 1.0) * 100.0
            ));
        }
        for t in &self.targets {
            let dist = cells.iter().map(|&k| {
                let p = xy(k);
                ((p.0 - t.x).powi(2) + (p.1 - t.y).powi(2)).sqrt()
            });
            let near = dist.fold(f32::INFINITY, f32::min);
            let to_goal = ((g.0 - t.x).powi(2) + (g.1 - t.y).powi(2)).sqrt();
            if near < 60.0 && to_goal > 60.0 {
                notes.push(format!("Passes {} ({near:.0} m away)", t.name));
            }
        }
        notes.push(
            match mode {
                Mode::Safe => "Safe mode: maximises distance from scarps and boulders",
                Mode::Balanced => "Balanced mode: trades some clearance for a shorter walk",
                Mode::Science => "Science mode: accepts steeper ground to reach more science",
            }
            .to_string(),
        );
        notes.truncate(5);

        Route {
            mode,
            path: simplify(cells, d),
            length_m: length,
            eta_min,
            dose_msv: dose_msv(eta_min, self.params.dose_msv_per_day),
            max_slope_deg: max_slope,
            min_clearance_m: min_clear.min(1e5),
            risk,
            cost,
            notes,
        }
    }
}

fn stamp_disk(mask: &mut Grid<bool>, o: &Obstacle) {
    let c = mask.cell_m;
    let (i0, i1) = (
        ((o.x - o.r) / c).floor() as isize,
        ((o.x + o.r) / c).ceil() as isize,
    );
    let (j0, j1) = (
        ((o.y - o.r) / c).floor() as isize,
        ((o.y + o.r) / c).ceil() as isize,
    );
    for j in j0..=j1 {
        for i in i0..=i1 {
            if mask.in_bounds(i, j) {
                let (x, y) = mask.center(i as usize, j as usize);
                if (x - o.x).powi(2) + (y - o.y).powi(2) <= o.r * o.r {
                    mask.set(i as usize, j as usize, true);
                }
            }
        }
    }
}

/// Douglas–Peucker 簡化（容許誤差 1 格），輸出 [x, y, z]。
fn simplify(cells: &[usize], d: &Grid<f32>) -> Vec<[f32; 3]> {
    let pts: Vec<[f32; 3]> = cells
        .iter()
        .map(|&k| {
            let (x, y) = d.center(k % d.w, k / d.w);
            [x, y, d.data[k]]
        })
        .collect();
    if pts.len() <= 2 {
        return pts;
    }
    let mut keep = vec![false; pts.len()];
    keep[0] = true;
    *keep.last_mut().unwrap() = true;
    let mut stack = vec![(0usize, pts.len() - 1)];
    let tol = d.cell_m;
    while let Some((a, b)) = stack.pop() {
        let (pa, pb) = (pts[a], pts[b]);
        let (dx, dy) = (pb[0] - pa[0], pb[1] - pa[1]);
        let len = (dx * dx + dy * dy).sqrt().max(1e-6);
        let (mut best, mut bi) = (0.0f32, a);
        for (i, p) in pts.iter().enumerate().take(b).skip(a + 1) {
            let dist = ((p[0] - pa[0]) * dy - (p[1] - pa[1]) * dx).abs() / len;
            if dist > best {
                best = dist;
                bi = i;
            }
        }
        if best > tol {
            keep[bi] = true;
            stack.push((a, bi));
            stack.push((bi, b));
        }
    }
    pts.into_iter()
        .zip(keep)
        .filter_map(|(p, k)| k.then_some(p))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::synth::{SynthSpec, generate};

    use std::sync::OnceLock;

    /// 用 demo 的實際解析度（1024² @ 2 m）；粗糙度和解析度有關，用粗網格會失真。只建一次，所有測試共用。
    fn planner() -> (&'static World, &'static Planner) {
        static P: OnceLock<(World, Planner)> = OnceLock::new();
        let (w, p) = P.get_or_init(|| {
            let w = generate(&SynthSpec::default());
            let p = Planner::new(&w, MissionParams::default());
            (w, p)
        });
        (w, p)
    }

    #[test]
    fn routes_avoid_hazards_and_reach_goal() {
        let (w, p) = planner();
        let goal = (w.targets[0].x, w.targets[0].y);
        for (m, r) in Mode::ALL.iter().zip(p.compare(w.base, goal)) {
            let r = r.unwrap_or_else(|e| panic!("{m:?}: {e:?}"));
            assert!(r.length_m > 0.0 && r.eta_min > 0.0);
            assert!(r.max_slope_deg <= p.thresholds.slope_max_deg + 1e-3);
            assert!((0.0..=1.0).contains(&r.risk));
            assert!(!r.notes.is_empty());
            let last = r.path.last().unwrap();
            assert!(
                ((last[0] - goal.0).powi(2) + (last[1] - goal.1).powi(2)).sqrt()
                    < SNAP_RADIUS_M + 4.0
            );
        }
    }

    #[test]
    fn safe_keeps_more_clearance_than_science() {
        let (w, p) = planner();
        let goal = (w.targets[0].x, w.targets[0].y);
        let [s, _, sc] = p.compare(w.base, goal);
        let (s, sc) = (s.unwrap(), sc.unwrap());
        assert!(
            s.min_clearance_m + 1e-3 >= sc.min_clearance_m,
            "safe {} < science {}",
            s.min_clearance_m,
            sc.min_clearance_m
        );
        assert!(s.risk <= sc.risk + 1e-3);
    }

    #[test]
    fn obstacle_forces_reroute() {
        let (w, p) = planner();
        let goal = (w.targets[0].x, w.targets[0].y);
        let r0 = p.route(w.base, goal, Mode::Balanced).unwrap();
        let mid = r0.path[r0.path.len() / 2];
        let obs = [Obstacle {
            x: mid[0],
            y: mid[1],
            r: 40.0,
        }];
        let p2 = p.with_obstacles(&obs);
        let r1 = p2.route(w.base, goal, Mode::Balanced).unwrap();
        for q in &r1.path {
            assert!(
                ((q[0] - mid[0]).powi(2) + (q[1] - mid[1]).powi(2)).sqrt() > 40.0 - 4.0,
                "path enters obstacle"
            );
        }
        let rp = p2
            .replan(w.base, goal, Mode::Balanced, true, 480.0)
            .unwrap();
        assert_eq!(rp.reason, "obstacle_rerouted");
    }

    #[test]
    fn pnr_shrinks_with_less_o2_and_triggers_return() {
        let (w, p) = planner();
        let count = |o2: f32| {
            p.pnr_mask(w.base, o2)
                .unwrap()
                .data
                .iter()
                .filter(|&&b| b)
                .count()
        };
        let (big, small) = (count(480.0), count(120.0));
        assert!(small < big, "{small} !< {big}");
        assert!(small > 0);
        let goal = (w.targets[0].x, w.targets[0].y);
        let rp = p.replan(w.base, goal, Mode::Safe, false, 35.0).unwrap();
        assert!(rp.must_return);
        assert_eq!(rp.reason, "goal_beyond_pnr");
    }

    #[test]
    fn drift_detection_on_route_vs_offset() {
        let (w, p) = planner();
        let goal = (w.targets[0].x, w.targets[0].y);
        let r = p.route(w.base, goal, Mode::Safe).unwrap();
        // 沿路線取幾個點：不應警告
        let total = crate::nav::cross_track(&r.path, w.base).total_m;
        for f in [0.2, 0.5, 0.8] {
            let q = crate::nav::point_along(&r.path, total * f);
            let s = p.track((q[0], q[1]), 1.0, &r.path, 25.0).unwrap();
            assert_eq!(s.status, RouteStatus::OnRoute, "at {f}: {s:?}");
        }
        // 在路線中段往側邊偏 40 m：要觸發重規劃
        let a = crate::nav::point_along(&r.path, total * 0.5);
        let b = crate::nav::point_along(&r.path, total * 0.5 + 5.0);
        let (dx, dy) = (b[0] - a[0], b[1] - a[1]);
        let n = (dx * dx + dy * dy).sqrt();
        let off = (a[0] - dy / n * 40.0, a[1] + dx / n * 40.0);
        let s = p.track(off, 1.0, &r.path, 25.0).unwrap();
        assert!(s.xte_m > 30.0, "{s:?}");
        assert_eq!(s.status, RouteStatus::Replan);
        // 從估計位置重規劃能回到目標
        assert!(
            p.replan(off, goal, Mode::Safe, false, 480.0)
                .unwrap()
                .route
                .is_some()
        );
    }

    #[test]
    fn coverage_layer_has_beacons() {
        let (w, p) = planner();
        let (i, j) = w.dem.to_cell(w.base.0, w.base.1).unwrap();
        assert!(
            p.coverage.get(i, j) >= 2.0,
            "base should see habitat + rover LoRa"
        );
        assert_eq!(p.beacons.len(), w.beacons.len());
    }
}
